powerpagecomponent.content:
{"copy":"{% if user %}
{% assign co = user.parentcustomerid.name | default: user.fullname %}
<main class=\"p-main\">
  <div class=\"row between\">
    <div>
      <h1>{{ co | escape }}</h1>
      <p class=\"sub\">One company account for CITF funding, disbursements and the Pre-approved List.</p>
    </div>
    <span class=\"pill ok\">Signed in</span>
  </div>
  <nav class=\"tabs\">
    <a class=\"on\" href=\"/\">Company profile</a>
    <a href=\"/documents/\">Document vault</a>
  </nav>
  <div class=\"card\">
    <h2>Company profile</h2>
    {% assign mail = user.emailaddress1 | default: \"\" %}
    {% assign acct = user.parentcustomerid.id | remove: \"{\" | remove: \"}\" %}
    {% fetchxml regs %}
    <fetch version=\"1.0\" mapping=\"logical\">
      <entity name=\"cicapos_companyregistration\">
        <attribute name=\"cicapos_name\" />
        <attribute name=\"cicapos_legalname\" />
        <attribute name=\"cicapos_legalnamezh\" />
        <attribute name=\"cicapos_companytype\" />
        <attribute name=\"cicapos_brnumber\" />
        <attribute name=\"cicapos_status\" />
        <attribute name=\"cicapos_bankname\" />
        <attribute name=\"cicapos_contactemail\" />
        <filter type=\"or\">
          {% if mail != \"\" %}<condition attribute=\"cicapos_contactemail\" operator=\"eq\" value=\"{{ mail }}\" />{% endif %}
          {% if acct != \"\" %}<condition attribute=\"cicapos_accountid\" operator=\"eq\" value=\"{{ acct }}\" />{% endif %}
          {% if mail == \"\" and acct == \"\" %}<condition attribute=\"cicapos_companyregistrationid\" operator=\"null\" />{% endif %}
        </filter>
      </entity>
    </fetch>
    {% endfetchxml %}
    {% if regs.results.entities.size > 0 %}
      {% assign r = regs.results.entities.first %}
      <div class=\"kv\">
        <span>Registration</span><span>{{ r.cicapos_name | escape }} · {{ r.cicapos_status.label | escape }}</span>
        <span>Legal name</span><span>{{ r.cicapos_legalname | escape }}{% if r.cicapos_legalnamezh %} · {{ r.cicapos_legalnamezh | escape }}{% endif %}</span>
        <span>Company type</span><span>{{ r.cicapos_companytype.label | escape }}</span>
        <span>BR number</span><span>{{ r.cicapos_brnumber | escape }}</span>
        <span>Contact email</span><span>{{ r.cicapos_contactemail | escape }}</span>
        <span>Bank</span><span>{{ r.cicapos_bankname | default: \"Not provided\" | escape }}</span>
      </div>
    {% else %}
      <p class=\"sub\">No company registration is linked to this sign-in yet.</p>
      <a class=\"btn\" href=\"/company-registration/\">Register your company</a>
    {% endif %}
  </div>
  <h2>Your CIC services</h2>
  <div class=\"grid g2\">
    <a class=\"card row\" href=\"/my-applications/\">
      <span class=\"kicker\">▣</span>
      <div>
        <h3>CITF Application Portal</h3>
        <span class=\"sub\">Apply for CITF funding, claim disbursements</span>
      </div>
    </a>
    <a class=\"card row\" href=\"/pre-approved-list/\">
      <span class=\"kicker\">▣</span>
      <div>
        <h3>Pre-approved List Portal</h3>
        <span class=\"sub\">Apply to list a product or request a change</span>
      </div>
    </a>
  </div>
</main>
{% else %}
<main class=\"p-main\">
  <div>
    <h1>CIC Company Portal</h1>
    <p class=\"sub\">One company account and one sign-in for CITF and other CIC services.</p>
  </div>
  <div class=\"card body\" style=\"max-width:560px\">
    <h2>Sign in</h2>
    <div class=\"note info\">Sign-in is handled by CIC’s Okta (OpenID Connect). MFA and password reset run in Okta.</div>
    <div class=\"f\">
      <label for=\"demo-email\">Email</label>
      <input id=\"demo-email\" name=\"email\" type=\"email\" value=\"carmen.lau@harbourbuild.example.com\" autocomplete=\"username\" />
    </div>
    <div class=\"f\">
      <label for=\"demo-password\">Password</label>
      <input id=\"demo-password\" name=\"password\" type=\"password\" value=\"Passw0rd!\" autocomplete=\"current-password\" />
    </div>
    <div class=\"row\">
      <a class=\"btn pri\" id=\"btn-okta\" href=\"/flow/?email=carmen.lau%40harbourbuild.example.com\">Sign in with Okta</a>
      <a class=\"btn ghost\" id=\"btn-iam\" href=\"/flow/?email=carmen.lau%40harbourbuild.example.com\">Sign in with iAM Smart (optional)</a>
    </div>
    <span>New company? <a href=\"/company-registration/\">Register your company</a> · Already registered, waiting for approval? <a href=\"/track/\">Track my registration</a></span>
  </div>
</main>
<script>
(function () {
  var d365 = {
    \"mandy.chan@cic.example.com\": \"Mandy Chan (Funding Application Vetting Officer)\",
    \"kelly.lau@cic.example.com\": \"Kelly Lau (PAL Application Vetting Officer)\",
    \"winnie.ho@cic.example.com\": \"Winnie Ho (Disbursement Vetting Officer)\",
    \"peter.yip@cic.example.com\": \"Peter Yip (Approver / Reviewer)\",
    \"eric.lam@cic.example.com\": \"Eric Lam (Finance Department)\",
    \"admin@cic.example.com\": \"Admin (Administrator)\"
  };
  function dest() {
    var email = String((document.getElementById(\"demo-email\") || {}).value || \"\").trim().toLowerCase()
      || \"carmen.lau@harbourbuild.example.com\";
    if (d365[email]) {
      return \"/flow/?d365=\" + encodeURIComponent(d365[email]) + \"#/d/dash\";
    }
    return \"/flow/?email=\" + encodeURIComponent(email);
  }
  function go(e) {
    e.preventDefault();
    location.href = dest();
  }
  var okta = document.getElementById(\"btn-okta\");
  var iam = document.getElementById(\"btn-iam\");
  if (okta) okta.addEventListener(\"click\", go);
  if (iam) iam.addEventListener(\"click\", go);
})();
</script>
{% endif %}
","displayorder":1,"enablerating":false,"enabletracking":false,"excludefromsearch":false,"feedbackpolicy":756150005,"hiddenfromsitemap":false,"isroot":false,"pagetemplateid":"0005c373-72eb-4494-8096-b7887c1d7c54","partialurl":"/","publishingstateid":"11327ec1-d362-4ca8-b603-20f7ed715821","rootwebpageid":"223204cd-dc77-4840-afd1-334ccce38916","sharedpageconfiguration":false,"summary":"<p>CIC Company Portal — CITF Application Portal &amp; Pre-approved List.</p>","title":"My Company"}
